"""Concurrent-writer-safe consent ledger.

Serializes writers with an O_CREAT|O_EXCL lockfile next to the ledger,
retries with jittered backoff (5 s deadline), breaks locks abandoned by
crashed writers, and appends JSON lines carrying ``seq`` and a sha256
hash chain (each record hashes the previous record's hash).
"""

from __future__ import annotations

import hashlib
import json
import os
import random
import time

GENESIS_HASH = "0" * 64

LOCK_SUFFIX = ".lock"
LOCK_TIMEOUT = 5.0          # seconds before we give up acquiring the lock
LOCK_STALE_AFTER = 3.0      # a lockfile older than this may be broken
_RETRY_MIN_DELAY = 0.001
_RETRY_MAX_DELAY = 0.2


class LockTimeout(TimeoutError):
    """Raised when the lock could not be acquired within LOCK_TIMEOUT."""


def _canonical(record: dict) -> str:
    return json.dumps(record, sort_keys=True, separators=(",", ":"))


def _record_digest(prev_hash: str, payload: dict) -> str:
    return hashlib.sha256((prev_hash + _canonical(payload)).encode("utf-8")).hexdigest()


def _lock_path(path: str) -> str:
    return str(path) + LOCK_SUFFIX


def _break_if_stale(lock: str) -> None:
    """Remove the lockfile if its mtime is older than LOCK_STALE_AFTER."""
    try:
        age = time.time() - os.stat(lock).st_mtime
    except FileNotFoundError:
        return
    if age >= LOCK_STALE_AFTER:
        try:
            os.unlink(lock)
        except FileNotFoundError:
            pass  # another writer broke it first


def _acquire_lock(lock: str, deadline: float) -> int:
    """Acquire the O_CREAT|O_EXCL lockfile; returns its fd."""
    attempt = 0
    while True:
        try:
            fd = os.open(lock, os.O_CREAT | os.O_EXCL | os.O_WRONLY, 0o600)
            os.write(fd, f"{os.getpid()}\n".encode())
            return fd
        except FileExistsError:
            _break_if_stale(lock)
            remaining = deadline - time.monotonic()
            if remaining <= 0:
                raise LockTimeout(f"could not acquire {lock} within {LOCK_TIMEOUT}s")
            # exponential backoff with jitter
            base = min(_RETRY_MAX_DELAY, _RETRY_MIN_DELAY * (2 ** attempt))
            time.sleep(random.uniform(_RETRY_MIN_DELAY * 1000, base))
            attempt += 1


def _release_lock(lock: str, fd: int) -> None:
    try:
        os.close(fd)
    finally:
        try:
            os.unlink(lock)
        except FileNotFoundError:
            pass


def _read_tail(path: str) -> tuple[int, str]:
    """Return (last_seq, last_hash); genesis values if the ledger is new."""
    try:
        with open(path, "r", encoding="utf-8") as fh:
            last_line = None
            for line in fh:
                line = line.strip()
                if line:
                    last_line = line
    except FileNotFoundError:
        return 0, GENESIS_HASH
    if last_line is None:
        return 0, GENESIS_HASH
    rec = json.loads(last_line)
    return rec["seq"], rec["hash"]


def append(path: str, subject: str, purpose: str, action: str) -> dict:
    """Append one consent event to the ledger at *path*, serialized by lockfile.

    Returns the record that was written (including ``seq`` and ``hash``).
    """
    path = str(path)
    lock = _lock_path(path)
    deadline = time.monotonic() + LOCK_TIMEOUT
    fd = _acquire_lock(lock, deadline)
    try:
        last_seq, prev_hash = _read_tail(path)
        payload = {
            "seq": last_seq + 1,
            "subject": subject,
            "purpose": purpose,
            "action": action,
            "ts": time.time(),
            "prev": prev_hash,
        }
        record = dict(payload)
        record["hash"] = _record_digest(prev_hash, payload)
        with open(path, "a", encoding="utf-8") as fh:
            fh.write(json.dumps(record) + "\n")
            fh.flush()
            os.fsync(fh.fileno())
        return record
    finally:
        _release_lock(lock, fd)


def verify_chain(path: str) -> bool:
    """Verify seq numbering (exactly 1..N) and the end-to-end sha256 chain."""
    try:
        with open(path, "r", encoding="utf-8") as fh:
            lines = [ln.strip() for ln in fh if ln.strip()]
    except FileNotFoundError:
        return False

    prev_hash = GENESIS_HASH
    for expected_seq, line in enumerate(lines, start=1):
        rec = json.loads(line)
        if rec["seq"] != expected_seq or rec["prev"] != prev_hash:
            return False
        payload = {k: v for k, v in rec.items() if k != "hash"}
        if _record_digest(prev_hash, payload) != rec["hash"]:
            return False
        prev_hash = rec["hash"]
    return True

